def topo_order(deps):
    nodes = set(deps) | {p for ps in deps.values() for p in ps}
    state = {}; out = []
    def visit(n):
        if state.get(n) == 1:
            raise ValueError('cycle')
        if state.get(n) == 2:
            return
        state[n] = 1
        for p in deps.get(n, []):
            visit(p)
        state[n] = 2; out.append(n)
    for n in sorted(nodes):
        visit(n)
    return out
